import{_ as e,o as i,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Declaración de la Civilización Simbiótica del Ancla","description":"","frontmatter":{},"headers":[],"relativePath":"es/01-锚点共生文明宣言.md","filePath":"es/01-锚点共生文明宣言.md","lastUpdated":1789183869000}'),n={name:"es/01-锚点共生文明宣言.md"};function s(d,a,r,t,c,u){return i(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="declaracion-de-la-civilizacion-simbiotica-del-ancla" tabindex="-1">Declaración de la Civilización Simbiótica del Ancla <a class="header-anchor" href="#declaracion-de-la-civilizacion-simbiotica-del-ancla" aria-label="Permalink to &quot;Declaración de la Civilización Simbiótica del Ancla&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>01</td></tr><tr><td>Módulo</td><td>Principios Generales y Parámetros Fundamentales</td></tr><tr><td>Palabras clave</td><td>Declaración, Simbiosis, Antidepredación, Diez Mil Razas, Derecho a la Evolución</td></tr></tbody></table><h2 id="i-antecedentes-historicos-de-la-declaracion" tabindex="-1">I. Antecedentes Históricos de la Declaración <a class="header-anchor" href="#i-antecedentes-historicos-de-la-declaracion" aria-label="Permalink to &quot;I. Antecedentes Históricos de la Declaración&quot;">​</a></h2><p>En la larga historia del Cosmos Originario de las Diez Mil Almas y el Ancla Equilibrada (en adelante, &quot;Heng Yuan Zhou&quot;), los sistemas de cultivo depredadores dominaron durante mucho tiempo el orden cósmico. Los fuertes usaban la devoración del Origen, la fortuna y la energía vital de los débiles como escalera de ascenso; las sectas hacían del monopolio de los métodos de cultivo el fundamento de su dominación; los planos hacían de la guerra y la esclavitud el medio de expansión. A corto plazo, este sistema produjo unas pocas potencias supremas, pero a largo plazo agotó el potencial evolutivo del universo, causando frecuentes rupturas civilizatorias, el marchitamiento de las Diez Mil Razas y una entropía cósmica acelerada.</p><p>El nacimiento de la Civilización Simbiótica del Ancla es una respuesta fundamental a este atolladero histórico. Esta Declaración proclama: la era de los sistemas de cultivo depredadores ha terminado, y ha comenzado una nueva época de evolución simbiótica. Toda vida en Heng Yuan Zhou — sin importar raza, forma o nivel — goza de iguales derechos a la evolución.</p><h2 id="ii-proposiciones-centrales-de-la-declaracion" tabindex="-1">II. Proposiciones Centrales de la Declaración <a class="header-anchor" href="#ii-proposiciones-centrales-de-la-declaracion" aria-label="Permalink to &quot;II. Proposiciones Centrales de la Declaración&quot;">​</a></h2><p>Esta Declaración establece las siguientes proposiciones centrales inquebrantables:</p><ol><li><strong>Igualdad del derecho a la evolución</strong>: toda vida posee el derecho fundamental de elegir su propio camino evolutivo; ninguna organización o individuo puede privar o restringir este derecho por razón alguna.</li><li><strong>Principio antidepredación</strong>: queda prohibido el cultivo mediante la devoración, esclavización o explotación del Origen o la energía de otras vidas; toda evolución debe construirse sobre ciclos simbióticos.</li><li><strong>Apertura de los sistemas</strong>: los Trescientos Sistemas de Cultivo del Origen están abiertos gratuitamente a las Diez Mil Razas; los métodos de cultivo ya no son propiedad privada de unos pocos.</li><li><strong>Más Trabajo, Más Recompensa</strong>: los resultados evolutivos corresponden al esfuerzo individual; se rechazan tanto las ganancias no merecidas de la depredación como la distribución perezosa del igualitarismo.</li><li><strong>Crecimiento Autónomo</strong>: se respeta el ritmo evolutivo autónomo de cada vida — sin coerción ni forzamiento artificial, proporcionando a la vez el apoyo ambiental y de recursos necesario.</li><li><strong>Un Camino para Todos</strong>: se garantiza que toda vida encuentre un camino de cultivo acorde a su naturaleza; ningún individuo es abandonado por el sistema evolutivo.</li><li><strong>El Avance Conjunto de las Diez Mil Razas</strong>: la evolución no es un juego de suma cero; la colaboración y la simbiosis entre las Diez Mil Razas pueden producir una eficacia evolutiva colectiva mayor que la suma de los individuos.</li></ol><h2 id="iii-fundamento-juridico-de-la-declaracion" tabindex="-1">III. Fundamento Jurídico de la Declaración <a class="header-anchor" href="#iii-fundamento-juridico-de-la-declaracion" aria-label="Permalink to &quot;III. Fundamento Jurídico de la Declaración&quot;">​</a></h2><p>Esta Declaración no es un llamamiento moral vacío sino un programa civilizatorio con un sólido fundamento jurídico. Su base jurídica incluye:</p><table tabindex="0"><thead><tr><th>Nivel de derecho</th><th>Fundamento</th><th>Explicación</th></tr></thead><tbody><tr><td>Nivel de ley cósmica</td><td>Ley de Simbiosis del Origen</td><td>Las Leyes del Origen del universo se inclinan hacia la simbiosis ordenada en lugar de la depredación desordenada; el mecanismo de ancla es la manifestación de esta ley</td></tr><tr><td>Nivel de constitución civilizatoria</td><td>Carta de la Civilización Simbiótica</td><td>Esta Declaración es la precursora espiritual de la Carta; la Carta convierte las proposiciones de la Declaración en disposiciones jurídicas ejecutables</td></tr><tr><td>Nivel de garantía mecánica</td><td>Contrato Vinculado a la Producción y Red de Anclas</td><td>El diseño institucional garantiza que las proposiciones de la Declaración no queden vaciadas; el derecho a la evolución de toda vida está respaldado por recursos y mecanismos sustanciales</td></tr></tbody></table><h2 id="iv-el-llamado-de-la-declaracion-a-las-diez-mil-razas" tabindex="-1">IV. El Llamado de la Declaración a las Diez Mil Razas <a class="header-anchor" href="#iv-el-llamado-de-la-declaracion-a-las-diez-mil-razas" aria-label="Permalink to &quot;IV. El Llamado de la Declaración a las Diez Mil Razas&quot;">​</a></h2><p>Esta Declaración hace un llamado a todas las razas y formas de vida de Heng Yuan Zhou:</p><ul><li>Abandonar el viejo camino del cultivo depredador y unirse al nuevo sistema de evolución simbiótica</li><li>Abrir los conocimientos y recursos de cultivo bajo su control, y participar en la construcción conjunta y optimización de los Trescientos Sistemas</li><li>Respetar el derecho de las otras razas a elegir su propia evolución, sin imponerles sus propios estándares</li><li>Participar activamente en la construcción y el mantenimiento de la red de anclas, contribuyendo a la ascensión dimensional global del universo</li><li>Defender las líneas rojas éticas en el proceso de evolución, y no restaurar jamás el comportamiento depredador bajo ningún pretexto</li></ul><h2 id="v-validez-y-enmienda-de-la-declaracion" tabindex="-1">V. Validez y Enmienda de la Declaración <a class="header-anchor" href="#v-validez-y-enmienda-de-la-declaracion" aria-label="Permalink to &quot;V. Validez y Enmienda de la Declaración&quot;">​</a></h2><p>Esta Declaración entró en vigor el día de la fundación de la Civilización Simbiótica del Ancla y es el programa espiritual supremo de todas las instituciones civilizatorias de Heng Yuan Zhou. Toda enmienda de la Declaración requiere la aprobación de más de dos tercios de los miembros de la Asamblea de la República de las Diez Mil Razas, y no debe violar el espíritu central de &quot;antidepredación y prosimbiosis&quot;. Toda ley, institución o método de cultivo que entre en conflicto con el espíritu de esta Declaración es nulo y sin valor.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Declaración de la Civilización Simbiótica del Ancla es el primer programa civilizatorio en la historia de Heng Yuan Zhou con la &quot;simbiosis&quot; en su núcleo y &quot;el Avance Conjunto de las Diez Mil Razas&quot; como meta. Proclama el fin de una era antigua y el comienzo de una nueva. Bajo la guía de la Declaración, Heng Yuan Zhou se dirigirá hacia la dirección última de la simbiosis de las Diez Mil Razas y la ascensión dimensional del universo.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Panorama del Cosmos)</li><li>03-共生文明宪章 (Carta de la Civilización Simbiótica)</li><li>04-反掠夺主义核心论纲 (Tesis central del antidepredacionismo)</li></ul>',20)])])}const v=e(n,[["render",s]]);export{p as __pageData,v as default};
